<?php require_once 'config/database.php'; require_once 'includes/auth.php'; require_login(); $items=cart_items($pdo); if(!$items) redirect('cart.php'); $totals=cart_totals($pdo); $page_title='Checkout'; include 'includes/header.php'; ?>
<div class="form-shell"><h1>Checkout</h1><p class="muted">Review your order and choose how to pay.</p><div class="notice"><strong>Order total: ₹<?= number_format($totals['total'],2) ?></strong><br><?= count($items) ?> item(s), including ₹40 delivery.</div><form id="checkout-form"><label>Delivery Address<textarea name="delivery_address" required><?= esc($_SESSION['user']['address']) ?></textarea></label><label>Payment Method<select name="payment_method" required><option value="Cash on Delivery">Cash on Delivery</option><option value="UPI">UPI</option><option value="Card">Card</option></select></label><div class="form-actions"><button type="submit">Place Order</button> <a class="button secondary" href="cart.php">Back to Cart</a></div><p id="checkout-message"></p></form></div><script>document.querySelector('#checkout-form').addEventListener('submit',async event=>{event.preventDefault(); const message=document.querySelector('#checkout-message'); const data=Object.fromEntries(new FormData(event.target)); message.textContent='Placing order...'; const result=await (await fetch('ajax/place_order.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})).json(); if(result.success) location.href='order_success.php?id='+result.order_id; else {message.textContent=result.message; message.className='error';}});</script><?php include 'includes/footer.php'; ?>